package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PolicyUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property policy uri of trusted client ")
  void test_policy_uri_v_o_builder() {
    Assertions.assertFalse(PolicyUriVO.nullValue().getPolicyUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PolicyUriVO.tryFrom(null).getPolicyUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", PolicyUriVO.from("one").getPolicyUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PolicyUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PolicyUriVO.from("one").toString());
  }
}
